/* @lc app=leetcode id=4013 lang=kotlin */ class Solution { fun countRatioSubarrays(nums: IntArray, a: Int, b: Int): Long = nums.runningFold(0L to 0L) { (e, o), v -> if (v % 2 == 0) e + 1 to o else e to o + 1 }.map { (e, o) -> e * b - o * a.toLong() }.let { K -> K.sorted().distinct().let { srt -> LongArray(srt.size + 2).let { bit -> K.withIndex().sumOf { (idx, k) -> (srt.binarySearch(k) + 1).let { rk -> (idx - generateSequence(rk - 1) { it - (it and -it) }.takeWhile { it > 0 }.sumOf { bit[it] }).also { generateSequence(rk) { it + (it and -it) }.takeWhile { it < bit.size }.forEach { bit[it]++ } } } } } } } }